BEGIN TRANSACTION;
CREATE TABLE academic_documents (
	id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36) NOT NULL, 
	document_type VARCHAR(50) NOT NULL, 
	document_number VARCHAR(100) NOT NULL, 
	program_id VARCHAR(36), 
	course_id VARCHAR(36), 
	issue_date DATE NOT NULL, 
	is_compliant BOOLEAN NOT NULL, 
	content_payload TEXT, 
	issued_by VARCHAR(100) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(program_id) REFERENCES programs (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
INSERT INTO "academic_documents" VALUES('67136485-a4ee-4fdd-aac5-b6e7e9971378','38f04fee-2821-4754-87ab-a9cda8efe45a','ALUMNO_REGULAR','CERT-AR-2026-0001','3df9b959-7caf-4f1a-95a7-969540c4355f',NULL,'2026-10-31',0,'{"folio": "CERT-AR-2026-0001", "institution": "Instituto de Medicina China Clásica SpA", "school_name": "Escuela San Bao", "rut_institution": "77.123.456-9", "issue_date": "31 de October de 2026", "student_rut": "19876543-0", "student_name": "Diego Valenzuela Morales", "student_number": "MAT-2026-0002", "program_name": "Diplomado Superior en Medicina China Tradicional", "program_code": "DIP-MTC-01", "degree_title": "Diplomado Superior en Medicina Tradicional China", "total_semesters": 2, "total_theoretical_hours": 240, "total_practical_hours": 120, "min_clinical_hours": 60, "clinical_hours_accredited": 16, "approved_courses_count": 1, "course_name": null, "course_code": null, "course_hours": null, "is_compliant": false, "notes": "Certificado oficial emitido para trámites de seguro y acreditación Minsal.", "legal_note": "Documento emitido conforme a las resoluciones académicas vigentes y a las facultades estatutarias del Instituto de Medicina China Clásica SpA.", "signatures": [{"role": "Rectoría Institucional", "name": "Dirección General San Bao SpA"}, {"role": "Dirección Académica", "name": "Dra. Marcela Pérez M."}, {"role": "Coordinación Académica", "name": "Lic. Camilo San Martín B."}]}','Coordinación Académica - Escuela San Bao','2026-10-31 23:04:16.152123','2026-10-31 23:04:16.152125',NULL);
CREATE TABLE academic_periods (
	id VARCHAR(36) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	year INTEGER NOT NULL, 
	semester_number INTEGER NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	is_enrollment_open BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id)
);
INSERT INTO "academic_periods" VALUES('fde2b8d9-8308-4e25-978a-2cfa3ec04a33','2026-I','Primer Semestre Académico 2026',2026,1,'2026-03-01','2026-07-31',1,1,'2026-10-31 23:04:16.038255','2026-10-31 23:04:16.038261',NULL);
CREATE TABLE access_logs (
	id VARCHAR(36) NOT NULL, 
	patient_id VARCHAR(36) NOT NULL, 
	encounter_id VARCHAR(36), 
	user_id VARCHAR(36) NOT NULL, 
	action VARCHAR(50) NOT NULL, 
	ip_address VARCHAR(50), 
	user_agent VARCHAR(255), 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE accounts_payable (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	supplier_rut VARCHAR(25) NOT NULL, 
	supplier_name VARCHAR(255) NOT NULL, 
	document_type VARCHAR(60) NOT NULL, 
	document_number VARCHAR(60) NOT NULL, 
	category VARCHAR(80) NOT NULL, 
	cost_center VARCHAR(120) NOT NULL, 
	business_unit VARCHAR(120) NOT NULL, 
	issue_date DATE NOT NULL, 
	due_date DATE NOT NULL, 
	total_amount NUMERIC(12, 0) NOT NULL, 
	paid_amount NUMERIC(12, 0) NOT NULL, 
	balance NUMERIC(12, 0) NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	payment_method VARCHAR(50), 
	paid_at DATE, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO "alembic_version" VALUES('3b35c8d26b23');
CREATE TABLE appointments (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	patient_id VARCHAR(36) NOT NULL, 
	practitioner_id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36), 
	campus_id VARCHAR(36) NOT NULL, 
	room_id VARCHAR(36) NOT NULL, 
	appointment_date DATE NOT NULL, 
	start_time VARCHAR(5) NOT NULL, 
	end_time VARCHAR(5) NOT NULL, 
	reason VARCHAR(255), 
	notes TEXT, 
	status VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE RESTRICT, 
	FOREIGN KEY(practitioner_id) REFERENCES practitioners (id) ON DELETE RESTRICT
);
