CREATE TABLE approval_workflows (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	workflow_type VARCHAR(60) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	origin_area VARCHAR(80) NOT NULL, 
	approver_area VARCHAR(80) NOT NULL, 
	requested_by VARCHAR(120) NOT NULL, 
	approved_by VARCHAR(120), 
	reference_code VARCHAR(80), 
	amount_clp NUMERIC(12, 0) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	comments TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	decided_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE assignments (
	id VARCHAR(36) NOT NULL, 
	lesson_id VARCHAR(36) NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	instructions TEXT NOT NULL, 
	max_score NUMERIC(4, 1) NOT NULL, 
	due_date DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(lesson_id) REFERENCES lessons (id) ON DELETE CASCADE
);
CREATE TABLE attendances (
	id VARCHAR(36) NOT NULL, 
	cohort_id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36) NOT NULL, 
	class_date DATE NOT NULL, 
	is_present BOOLEAN NOT NULL, 
	is_excused BOOLEAN NOT NULL, 
	notes VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, course_id VARCHAR(36), class_number INTEGER, session_topic VARCHAR(255), status VARCHAR(20) DEFAULT 'PRESENTE', 
	PRIMARY KEY (id), 
	FOREIGN KEY(cohort_id) REFERENCES cohorts (id) ON DELETE CASCADE, 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE
);
