CREATE TABLE audit_logs (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36), 
	company_id VARCHAR(36), 
	module VARCHAR(50) NOT NULL, 
	action VARCHAR(50) NOT NULL, 
	entity_type VARCHAR(100) NOT NULL, 
	entity_id VARCHAR(100), 
	ip_address VARCHAR(50), 
	user_agent VARCHAR(255), 
	details TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE budget_items (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	period_year INTEGER NOT NULL, 
	cost_center VARCHAR(120) NOT NULL, 
	business_unit VARCHAR(120) NOT NULL, 
	category VARCHAR(120) NOT NULL, 
	item_name VARCHAR(255) NOT NULL, 
	budget_type VARCHAR(20) NOT NULL, 
	budgeted_amount NUMERIC(12, 0) NOT NULL, 
	executed_amount NUMERIC(12, 0) NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE business_units (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	campus_id VARCHAR(36), 
	code VARCHAR(50) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_finance_business_unit_company_code UNIQUE (company_id, code)
);
