CREATE TABLE curriculum_courses (
	id VARCHAR(36) NOT NULL, 
	curriculum_id VARCHAR(36) NOT NULL, 
	course_id VARCHAR(36) NOT NULL, 
	semester INTEGER NOT NULL, 
	is_mandatory BOOLEAN NOT NULL, 
	prerequisite_course_id VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id) ON DELETE CASCADE, 
	FOREIGN KEY(curriculum_id) REFERENCES curriculums (id) ON DELETE CASCADE, 
	FOREIGN KEY(prerequisite_course_id) REFERENCES courses (id)
);
CREATE TABLE curriculums (
	id VARCHAR(36) NOT NULL, 
	program_id VARCHAR(36) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	version_name VARCHAR(100) NOT NULL, 
	effective_year INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(program_id) REFERENCES programs (id) ON DELETE CASCADE
);
CREATE TABLE digital_signatures (
	id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	document_type VARCHAR(100) NOT NULL, 
	document_id UUID NOT NULL, 
	signer_person_id UUID NOT NULL, 
	document_hash VARCHAR(64) NOT NULL, 
	signature_token VARCHAR(128) NOT NULL, 
	signer_ip VARCHAR(45), 
	status VARCHAR(50) NOT NULL, 
	signed_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (signature_token)
);
CREATE TABLE dte_documents (
	id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	dte_type INTEGER NOT NULL, 
	folio INTEGER NOT NULL, 
	issue_date DATE NOT NULL, 
	issuer_rut VARCHAR(20) NOT NULL, 
	issuer_name VARCHAR(255) NOT NULL, 
	receiver_rut VARCHAR(20) NOT NULL, 
	receiver_name VARCHAR(255) NOT NULL, 
	receiver_address VARCHAR(255), 
	receiver_commune VARCHAR(100), 
	receiver_activity VARCHAR(255), 
	net_amount NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	exempt_amount NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	iva_amount NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	total_amount NUMERIC(12, 2) NOT NULL, 
	items JSON NOT NULL, 
	sii_status VARCHAR(50) NOT NULL, 
	sii_track_id VARCHAR(50), 
	digital_stamp TEXT, 
	pdf_url VARCHAR(255), 
	reference_id UUID, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE encounters (
	id VARCHAR(36) NOT NULL, 
	patient_id VARCHAR(36) NOT NULL, 
	appointment_id VARCHAR(36), 
	practitioner_id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36), 
	encounter_date DATETIME NOT NULL, 
	reason_for_consultation TEXT NOT NULL, 
	current_illness_history TEXT, 
	traditional_anamnesis JSON, 
	tongue_diagnosis JSON, 
	pulse_diagnosis JSON, 
	zang_fu_syndrome VARCHAR(255), 
	eight_principles JSON, 
	therapeutic_principle TEXT, 
	treatment_plan JSON, 
	recommendations TEXT, 
	tutor_feedback TEXT, 
	tutor_grade NUMERIC(3, 1), 
	status VARCHAR(50) NOT NULL, 
	signed_at DATETIME, 
	signed_by VARCHAR(36), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE SET NULL, 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE RESTRICT, 
	FOREIGN KEY(practitioner_id) REFERENCES practitioners (id) ON DELETE RESTRICT, 
	UNIQUE (appointment_id)
);
CREATE TABLE enrollments (
	id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36) NOT NULL, 
	program_id VARCHAR(36) NOT NULL, 
	academic_period_id VARCHAR(36) NOT NULL, 
	enrollment_date DATE NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(academic_period_id) REFERENCES academic_periods (id) ON DELETE RESTRICT, 
	FOREIGN KEY(program_id) REFERENCES programs (id) ON DELETE RESTRICT, 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE
);
