CREATE TABLE hr_attendance_records (
	id UUID NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	employee_id UUID NOT NULL, 
	attendance_date DATE NOT NULL, 
	shift_name VARCHAR(100) NOT NULL, 
	check_in VARCHAR(10), 
	check_out VARCHAR(10), 
	worked_hours NUMERIC(5, 2) NOT NULL, 
	overtime_hours NUMERIC(5, 2) NOT NULL, 
	late_minutes INTEGER NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	modality VARCHAR(40) NOT NULL, 
	notes TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id)
);
CREATE TABLE hr_contracts (
	id UUID NOT NULL, 
	employee_id UUID NOT NULL, 
	contract_type VARCHAR(50) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	base_salary NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	hourly_rate NUMERIC(10, 2) DEFAULT '0.00' NOT NULL, 
	clinical_commission_pct NUMERIC(5, 2) DEFAULT '0.00' NOT NULL, 
	weekly_hours INTEGER DEFAULT '40' NOT NULL, 
	afp_name VARCHAR(50), 
	health_system VARCHAR(50), 
	health_quote_pct NUMERIC(5, 2) DEFAULT '7.00' NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	document_url VARCHAR(255), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id)
);
CREATE TABLE hr_employees (
	id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	person_id UUID NOT NULL, 
	employee_number VARCHAR(50) NOT NULL, 
	job_title VARCHAR(100) NOT NULL, 
	department VARCHAR(100) NOT NULL, 
	employee_type VARCHAR(50) NOT NULL, 
	hire_date DATE NOT NULL, 
	termination_date DATE, 
	status VARCHAR(50) NOT NULL, 
	notes TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	is_active BOOLEAN DEFAULT '1' NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE hr_fee_receipts (
	id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	employee_id UUID NOT NULL, 
	receipt_number VARCHAR(50) NOT NULL, 
	issue_date DATE NOT NULL, 
	period_month INTEGER NOT NULL, 
	period_year INTEGER NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	gross_amount NUMERIC(12, 2) NOT NULL, 
	retention_rate NUMERIC(5, 2) DEFAULT '13.75' NOT NULL, 
	retention_amount NUMERIC(12, 2) NOT NULL, 
	net_amount NUMERIC(12, 2) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	payment_date DATE, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id)
);
CREATE TABLE hr_labor_documents (
	id UUID NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	employee_id UUID NOT NULL, 
	document_type VARCHAR(60) NOT NULL, 
	document_code VARCHAR(60) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	issue_date DATE NOT NULL, 
	expiry_date DATE, 
	status VARCHAR(30) NOT NULL, 
	file_url VARCHAR(255), 
	verified_by VARCHAR(120), 
	notes TEXT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id)
);
CREATE TABLE hr_leave_requests (
	id UUID NOT NULL, 
	employee_id UUID NOT NULL, 
	leave_type VARCHAR(50) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	days_count INTEGER NOT NULL, 
	reason TEXT, 
	status VARCHAR(50) NOT NULL, 
	approved_by UUID, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id)
);
CREATE TABLE hr_payrolls (
	id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	employee_id UUID NOT NULL, 
	contract_id UUID NOT NULL, 
	period_month INTEGER NOT NULL, 
	period_year INTEGER NOT NULL, 
	worked_days INTEGER DEFAULT '30' NOT NULL, 
	base_salary NUMERIC(12, 2) NOT NULL, 
	legal_gratuity NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	bonuses NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	overtime_amount NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	gross_taxable_salary NUMERIC(12, 2) NOT NULL, 
	non_taxable_allowances NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	total_earnings NUMERIC(12, 2) NOT NULL, 
	pension_deduction NUMERIC(12, 2) NOT NULL, 
	health_deduction NUMERIC(12, 2) NOT NULL, 
	unemployment_insurance NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	income_tax NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	other_deductions NUMERIC(12, 2) DEFAULT '0.00' NOT NULL, 
	total_deductions NUMERIC(12, 2) NOT NULL, 
	net_salary NUMERIC(12, 2) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	payment_date DATE, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(employee_id) REFERENCES hr_employees (id), 
	FOREIGN KEY(contract_id) REFERENCES hr_contracts (id)
);
CREATE TABLE installments (
	id VARCHAR(36) NOT NULL, 
