	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(commitment_id) REFERENCES payment_commitments (id) ON DELETE CASCADE
);
CREATE TABLE journal_entries (
