CREATE TABLE shift_supply_dispatches (
	id VARCHAR(36) NOT NULL, 
	company_id VARCHAR(36) NOT NULL, 
	campus_id VARCHAR(36) NOT NULL, 
	practitioner_id VARCHAR(36) NOT NULL, 
	dispatcher_user_id VARCHAR(36) NOT NULL, 
	room_id VARCHAR(36), 
	dispatch_code VARCHAR(50) NOT NULL, 
	shift_date DATE NOT NULL, 
	shift_type VARCHAR(30) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	delivered_at DATETIME NOT NULL, 
	returned_at DATETIME, 
	return_verified_by_user_id VARCHAR(36), 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(practitioner_id) REFERENCES practitioners (id)
);
CREATE TABLE shift_supply_items (
	id VARCHAR(36) NOT NULL, 
	dispatch_id VARCHAR(36) NOT NULL, 
	supply_id VARCHAR(36) NOT NULL, 
	quantity_delivered INTEGER NOT NULL, 
	quantity_used INTEGER NOT NULL, 
	quantity_returned INTEGER NOT NULL, 
	condition_notes VARCHAR(255), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(dispatch_id) REFERENCES shift_supply_dispatches (id) ON DELETE CASCADE, 
	FOREIGN KEY(supply_id) REFERENCES clinical_supplies (id)
);
CREATE TABLE student_course_transfers (
	id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36) NOT NULL, 
	from_program_id VARCHAR(36) NOT NULL, 
	to_program_id VARCHAR(36) NOT NULL, 
	transfer_date DATE NOT NULL, 
	reason VARCHAR(255) NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(from_program_id) REFERENCES programs (id), 
	FOREIGN KEY(to_program_id) REFERENCES programs (id)
);
CREATE TABLE student_onboardings (
	id VARCHAR(36) NOT NULL, 
	student_id VARCHAR(36) NOT NULL, 
	person_id VARCHAR(36) NOT NULL, 
	enrollment_id VARCHAR(36), 
	program_id VARCHAR(36) NOT NULL, 
	commitment_id VARCHAR(36), 
	legal_document_id VARCHAR(36), 
	enrollment_fee NUMERIC(12, 0) NOT NULL, 
	tuition_amount NUMERIC(12, 0) NOT NULL, 
	installments_count INTEGER NOT NULL, 
	contract_code VARCHAR(60), 
	contract_sign_link VARCHAR(500), 
	contract_email_sent BOOLEAN NOT NULL, 
	signature_token VARCHAR(128), 
	document_hash VARCHAR(64), 
	contract_signed_at VARCHAR(60), 
	webpay_token VARCHAR(120), 
	webpay_link VARCHAR(500), 
	webpay_amount NUMERIC(12, 0) NOT NULL, 
	webpay_auth_code VARCHAR(60), 
	webpay_paid_at VARCHAR(60), 
	dte_folio INTEGER, 
	portal_username VARCHAR(50), 
	portal_temp_password VARCHAR(100), 
	portal_user_id VARCHAR(36), 
	status VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id) ON DELETE CASCADE, 
	FOREIGN KEY(enrollment_id) REFERENCES enrollments (id) ON DELETE SET NULL, 
	FOREIGN KEY(program_id) REFERENCES programs (id) ON DELETE RESTRICT
);
CREATE TABLE students (
	id VARCHAR(36) NOT NULL, 
	person_id VARCHAR(36) NOT NULL, 
	student_number VARCHAR(50) NOT NULL, 
	admission_date DATE NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	notes VARCHAR(500), 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	deleted_at DATETIME, freeze_reason VARCHAR(255), freeze_date DATE, clinical_practice_approved BOOLEAN DEFAULT 0, clinical_practice_approval_date DATE, clinical_practice_notes TEXT, 
	PRIMARY KEY (id)
);
